function getFields() {
  var allFields = [];
  for (var rawFieldName in daVarLookup) {
    if (daVarLookup.hasOwnProperty(rawFieldName)) {
      var fieldName = atou(rawFieldName);
      if (allFields.indexOf(fieldName) == -1) {
        allFields.push(fieldName);
      }
    }
  }
  return allFields;
}
